        '{problems}. Wi-Fi needs a wireless NIC (wlan0, wlp1s0); cables need an Ethernet port.': '{problems}. El Wi-Fi necesita una NIC inalámbrica (wlan0, wlp1s0); los cables necesitan un puerto Ethernet.',
