        'Paste rows copied from a spreadsheet, or open a CSV file. Rows are matched to devices by id, MAC, IP or name; a row that matches none adds a device. Nothing changes until you apply it.': 'Pega filas copiadas de una hoja de cálculo o abre un archivo CSV. Las filas se emparejan con dispositivos por id, MAC, IP o nombre; una fila que no coincide con ninguno añade un dispositivo. Nada cambia hasta que lo apliques.',
