        'Only a switch or an access point has numbered ports.': 'Solo un switch o un punto de acceso tiene puertos numerados.',
        'A prefix cannot end in a digit: the port number would run into it. End it with a separator, such as / or a space.': 'Un prefijo no puede terminar en un dígito: el número del puerto se juntaría con él. Termínelo con un separador, como / o un espacio.',
        'Say which port: map the port column.': 'Indica qué puerto: asigna la columna del puerto.',
        'A sheet of ports maps the device, the port and its label or VLAN. Leave the other columns unmapped.': 'Una hoja de puertos asigna el dispositivo, el puerto y su etiqueta o VLAN. Deja sin asignar las demás columnas.',
        'Seen as {name}.': 'Visto como {name}.',
