        'Read as': 'Leer como',
        'Spreadsheet rows': 'Filas de hoja de cálculo',
        'Addresses seen (ARP, DHCP)': 'Direcciones vistas (ARP, DHCP)',
        'Or paste an ARP table or a DHCP lease list as a router, a switch, a server or a PC prints it, from any vendor: each address seen with its MAC becomes a row.': 'O pega una tabla ARP o una lista de concesiones DHCP tal como la imprime un router, un switch, un servidor o un PC, de cualquier fabricante: cada dirección vista con su MAC se convierte en una fila.',
