        'From port': 'Desde el puerto',
        'There is no switch or access point on the map to move them to.': 'No hay ningún switch ni punto de acceso en el mapa al que moverlos.',
        "Each one's cable moves to the next free port there. The device keeps its address: Move gives it one on another subnet.": 'El cable de cada uno pasa al siguiente puerto libre de allí. El dispositivo conserva su dirección: Mover le da una en otra subred.',
        'Pick a switch to move them to.': 'Elige un switch al que moverlos.',
        'This is the switch they are moving to.': 'Este es el switch al que se mueven.',
        'Already on {switch}.': 'Ya está en {switch}.',
        'Cabled to more than one switch: re-cable it by hand.': 'Conectado a más de un switch: recabléalo a mano.',
        'More than one cable: re-cable it by hand.': 'Más de un cable: recabléalo a mano.',
        'Not on a switch port: re-cable it by hand.': 'No está en un puerto de switch: recabléalo a mano.',
