        'File': 'Archivo',
        'Opens netplan.carino.systems pre-filled from this device (netplan / systemd-networkd / NetworkManager). Review the guessed fields before applying anything.': 'Abre netplan.carino.systems con los datos de este dispositivo (netplan / systemd-networkd / NetworkManager). Revisa los campos deducidos antes de aplicar nada.',
        'Rows of subnets: {n}': 'Filas de subredes: {n}',
        'A sheet of subnets maps only what a subnet has: its CIDR, name, VLAN, gateway and so on. Leave the other columns unmapped.': 'Una hoja de subredes asigna solo lo que tiene una subred: su CIDR, nombre, VLAN, puerta de enlace, etc. Deja sin asignar las demás columnas.',
        '{cidr} is not the range of this subnet ({now}). Renumber it in the Subnets tab, which moves its devices with it.': '{cidr} no es el rango de esta subred ({now}). Renumérala en la pestaña Subnets, que mueve sus dispositivos con ella.',
        '{id} and {cidr} are two different subnets.': '{id} y {cidr} son dos subredes distintas.',
        'A new subnet needs its CIDR, like 10.0.9.0/24.': 'Una subred nueva necesita su CIDR, como 10.0.9.0/24.',
        "Found {name} by {key} only, but the row's {fields} belong to another device. Correct the sheet or the map so the two agree.": 'Se encontró {name} solo por {key}, pero {fields} de la fila son de otro dispositivo. Corrige la hoja o el mapa para que coincidan.',
        'The pattern has no {type}, so every kind shares one run of numbers.': 'El patrón no tiene {type}, así que todos los tipos comparten una misma numeración.',
        'Fold every wired NIC into one bond: one MAC, one address': 'Agrupa todas las NIC cableadas en un bond: una MAC, una dirección',
        'Show the hardware address under each interface — paste one and it is decoded': 'Muestra la dirección de hardware bajo cada interfaz: pega una y se decodifica',
        "NAT hides this device's private (inside) subnets from the WAN side — only the gateway itself is reachable from outside.": 'La NAT oculta las subredes privadas (internas) de este dispositivo al lado WAN: desde fuera solo se alcanza la propia puerta de enlace.',
        'Say that this cloud stands for another network in your binder, so the estate report can draw the link between them.': 'Indica que esta nube representa otra red de tu carpeta, para que el informe del conjunto dibuje el enlace entre ambas.',
