        "{iface} is on channel {ch}, which 6 GHz does not have (1 to 233, in steps of 4: 1, 5, 9…).": "{iface} está en el canal {ch}, que 6 GHz no tiene (1 a 233, de 4 en 4: 1, 5, 9…).",
