        "{iface} lists 6 GHz, but {standard} has no 6 GHz: that takes Wi-Fi 6E or Wi-Fi 7.": "{iface} incluye 6 GHz, pero {standard} no tiene 6 GHz: para eso hace falta Wi-Fi 6E o Wi-Fi 7.",
        "{a} and {b} are on 6 GHz, but {name} is {standard}. 6 GHz takes Wi-Fi 6E or Wi-Fi 7 at both ends.": "{a} y {b} están en 6 GHz, pero {name} es {standard}. 6 GHz requiere Wi-Fi 6E o Wi-Fi 7 en ambos extremos.",
