        'Paste rows copied from a spreadsheet, or open a CSV file. Rows are matched to devices by id, MAC, IP or name; a row that matches none adds a device. Nothing changes until you apply it.': 'Cole linhas copiadas de uma planilha ou abra um arquivo CSV. As linhas são associadas aos dispositivos por id, MAC, IP ou nome; uma linha que não corresponde a nenhum adiciona um dispositivo. Nada muda até você aplicar.',
