        'File': 'Arquivo',
        'Opens netplan.carino.systems pre-filled from this device (netplan / systemd-networkd / NetworkManager). Review the guessed fields before applying anything.': 'Abre o netplan.carino.systems preenchido com os dados deste dispositivo (netplan / systemd-networkd / NetworkManager). Revise os campos deduzidos antes de aplicar qualquer coisa.',
        'Rows of subnets: {n}': 'Linhas de sub-redes: {n}',
        'A sheet of subnets maps only what a subnet has: its CIDR, name, VLAN, gateway and so on. Leave the other columns unmapped.': 'Uma planilha de sub-redes mapeia só o que uma sub-rede tem: CIDR, nome, VLAN, gateway e assim por diante. Deixe as demais colunas sem mapear.',
        '{cidr} is not the range of this subnet ({now}). Renumber it in the Subnets tab, which moves its devices with it.': '{cidr} não é a faixa desta sub-rede ({now}). Renumere-a na aba Subnets, que move os dispositivos junto.',
