        'The connection cannot work the way it is documented.': 'Соединение не может работать так, как записано.',
        'A hardware address on a device looks wrong': 'Аппаратный адрес устройства выглядит неправильно',
        'The device may be hard to identify, or clash with another one.': 'Устройство может быть трудно опознать, или оно может конфликтовать с другим.',
        'A device cannot reach the way out of its network': 'Устройство не может добраться до выхода из своей сети',
        'It may not reach the internet or the other networks.': 'Оно может не выходить в интернет и в другие сети.',
        'The name server of a device cannot be reached': 'Сервер имён устройства недоступен',
        'Websites and services may not open by their names.': 'Сайты и сервисы могут не открываться по имени.',
        // Columns (js/table.js "The Columns dialog") and custom columns
        'Columns…': 'Столбцы…',
        'Show, hide and reorder the columns, and add your own': 'Показать, скрыть и переставить столбцы, добавить свои',
        'Columns': 'Столбцы',
        'Which columns the Devices table shows, and in what order. It is saved with the network, and your columns that show here are printed in the report. Spreadsheets keep their own order, so a sheet always reads back.': 'Какие столбцы показывает таблица устройств и в каком порядке. Сохраняется вместе с сетью, а ваши столбцы, показанные здесь, печатаются в отчёте. В таблицах-файлах порядок свой, поэтому файл всегда читается обратно.',
        'What is written on {names} looks like it holds a password. Whoever gets this can read it: take it out first, or keep it somewhere else.': 'Похоже, в записях на {names} есть пароль. Любой, кто это получит, сможет его прочитать: сначала уберите его или храните в другом месте.',
        'One device holds a value in {name} that is not a {kind}: it will be lost.': 'У одного устройства в столбце {name} значение, не подходящее под тип «{kind}»: оно будет потеряно.',
        '{n} devices hold a value in {name} that is not a {kind}: they will be lost.': 'Устройств со значением в столбце {name}, не подходящим под тип «{kind}»: {n}. Эти значения будут потеряны.',
        'Add a column': 'Добавить столбец',
        'Column name': 'Название столбца',
        'Number': 'Число',
        'Yes / no': 'Да / нет',
        'Reset order': 'Сбросить порядок',
        'A column needs a name.': 'У столбца должно быть название.',
