        'A network can have at most {n} columns of its own.': 'Своих столбцов в сети может быть не больше {n}.',
        'Delete the column {name}? One device loses what it holds.': 'Удалить столбец {name}? Одно устройство потеряет его значение.',
        'Delete the column {name}? {n} devices lose what it holds.': 'Удалить столбец {name}? Устройств, которые потеряют его значение: {n}.',
        'Delete column': 'Удалить столбец',
