        'Your columns': 'Ваши столбцы',
        'Makes the columns: {names}': 'Будут созданы столбцы: {names}',
        'Custom columns': 'Свои столбцы',
        'Paste a column': 'Вставить столбец',
        'Paste a list of values into one column, one per row, with a preview first': 'Вставить список значений в один столбец, по одному на строку, с предварительным просмотром',
        'Click a row to find it on the map. Enter or a double click edits a cell, Esc cancels. Ctrl+V pastes a list down a column.': 'Щёлкните строку, чтобы найти её на карте. Enter или двойной щелчок — правка ячейки, Esc — отмена. Ctrl+V вставляет список вниз по столбцу.',
        'Nothing here yet.': 'Здесь пока ничего нет.',
        'Select every row': 'Выделить все строки',
        'Show interfaces': 'Показать интерфейсы',
        'Hide interfaces': 'Скрыть интерфейсы',
        'Rows: {n}': 'Строк: {n}',
        'Selected: {n}': 'Выделено: {n}',
        '{value} is not a valid {field}.': '{value} — недопустимое значение для поля {field}.',
        'Nothing was changed.': 'Ничего не изменено.',
        'One value per line, in the order the rows are shown. A blank line leaves its row as it is.': 'По одному значению на строку, в том порядке, в каком показаны строки. Пустая строка оставляет свою строку без изменений.',
        'Into the selected rows, in the order shown.': 'В выделенные строки, в показанном порядке.',
        'Into the rows from {name} down, in the order shown.': 'В строки начиная с {name} и ниже, в показанном порядке.',
