        'The findings stay the same.': 'Выводы не изменятся.',
        'Cells changed: {n}': 'Изменено ячеек: {n}',
        // The bulk panel (plan 3.4, js/bulk.js).
        'Yes': 'Да',
        'No': 'Нет',
        'Only a routing device does NAT.': 'NAT выполняет только маршрутизирующее устройство.',
        'The name does not contain {text}.': 'В имени нет {text}.',
        'A device needs a name.': 'У устройства должно быть имя.',
        'Devices that would share a name with another: {n}': 'Устройств, чьё имя совпадёт с другим: {n}',
        'Without {n} in the pattern, every device gets the same name.': 'Без {n} в шаблоне все устройства получат одно и то же имя.',
        'Pick a subnet to move them to.': 'Выберите подсеть, в которую их перенести.',
        'A router or firewall keeps its addresses: change them on the device.': 'Маршрутизатор или межсетевой экран сохраняет свои адреса: меняйте их на самом устройстве.',
        'Already on {network}.': 'Уже в {network}.',
        'No interface to give an address to.': 'Нет интерфейса, которому можно дать адрес.',
        'A switch or access point with no address of its own stays without one.': 'Коммутатор или точка доступа без собственного адреса так и остаётся без него.',
