        'Labels': 'Этикетки',
        'Print': 'Печать',
        'Sized for 62 × 29 mm labels, one per page. A cable gets two: one for each end.': 'Размер для этикеток 62 × 29 мм, по одной на страницу. На кабель — две: по одной на каждый конец.',
        'Give a device an asset tag first: its label is the tag and its QR code.': 'Сначала задайте устройству инвентарный номер: этикетка — это номер и его QR-код.',
