        "{a} is on {ssid}, whose subnet is {cidr}, but its address {ip} is not in it.": "{a} в сети {ssid} с подсетью {cidr}, но его адрес {ip} в неё не входит.",
        "{a} hears {b} at {signal} dBm. A phone needs {limit} dBm or better for calls that do not break up.": "{a} слышит {b} на уровне {signal} dBm. Телефону нужно {limit} dBm или лучше, чтобы звонки не прерывались.",
