        "{ssid} allows WPA (TKIP), which is retired and weak, and which Wi-Fi 6 devices will not use. Use WPA2/WPA3.": "{ssid} допускает WPA (TKIP) — устаревший и слабый, к тому же устройства Wi-Fi 6 его не используют. Используйте WPA2/WPA3.",
