        'What is written on {names} looks like it holds a password. Whoever gets this can read it: take it out first, or keep it somewhere else.': '{names} に書かれた内容にパスワードが含まれているようです。受け取った人は誰でも読めます。先に削除するか、別の場所に保管してください。',
