        'A saved selection. It goes in beside what you have, moved to the next free subnet.': '保存した選択範囲です。既存の構成の横に、次に空いているサブネットで配置されます。',
        'My blocks': 'マイブロック',
        // Spreadsheets: the CSV / TSV round-trip (plan 3.5, js/csv.js).
        'Spreadsheet': 'スプレッドシート',
        'Import': 'インポート',
        'Each sheet is a CSV file any spreadsheet opens (UTF-8, accents and all). Copy as TSV puts the same rows on the clipboard, to paste straight into an open sheet.': '各シートはどの表計算ソフトでも開ける CSV ファイルです (UTF-8、日本語もそのまま)。「TSV としてコピー」は同じ行をクリップボードに入れ、開いているシートにそのまま貼り付けられます。',
        'Paste rows copied from a spreadsheet, or open a CSV file. Rows are matched to devices by id, MAC, IP or name; a row that matches none adds a device. Nothing changes until you apply it.': '表計算ソフトからコピーした行を貼り付けるか、CSV ファイルを開いてください。各行は id、MAC、IP、名前の順でデバイスと照合され、どれにも一致しない行はデバイスとして追加されます。適用するまで何も変わりません。',
