        'Pick what at least one column is.': '少なくとも 1 つの列が何かを指定してください。',
        '{value} needs its prefix (for example {value}/24): it is in no network on the map.': '{value} にはプレフィックスが必要です (例: {value}/24)。マップ上のどのネットワークにも含まれていません。',
        'Matches {n} devices by {key}: add an id or a MAC to say which.': '{key} で {n} 台のデバイスに一致します。どれかを示すには id か MAC を追加してください。',
        'Nothing to find or name this device by: map a name, an address or an id.': 'このデバイスを探す手がかりも名前もありません。名前、アドレス、id のいずれかを割り当ててください。',
        'Another row sets {field} to {value}.': '別の行が {field} を {value} にしています。',
