        '{name} has {ports} ports: port {port} is past its faceplate and shows as a port overflow.': '{name} のポートは{ports}個です。ポート{port}はそれを超えるため、ポート超過として表示されます。',
        '{name} has no port {port}.': '{name} にポート {port} はありません。',
