        'Only a switch or an access point has numbered ports.': '番号付きのポートがあるのはスイッチかアクセスポイントだけです。',
        'A prefix cannot end in a digit: the port number would run into it. End it with a separator, such as / or a space.': 'プレフィックスの末尾に数字は使えません。ポート番号とつながってしまいます。/ や空白などの区切りで終えてください。',
        'Say which port: map the port column.': 'ポートを指定してください: ポートの列を割り当ててください。',
        'A sheet of ports maps the device, the port and its label or VLAN. Leave the other columns unmapped.': 'ポートのシートでは、デバイス、ポート、そのラベルまたは VLAN を割り当てます。ほかの列は割り当てないでください。',
        'Seen as {name}.': '{name} として検出。',
        'A device on the map is also called {name}: a name seen on the network is not used to find one.': 'マップ上にも {name} という名前の機器があります。ネットワークで見えた名前は機器の特定には使いません。',
        'Read as': '読み取り方法',
