        'Addresses seen (ARP, DHCP)': '検出されたアドレス (ARP、DHCP)',
        'Or paste an ARP table or a DHCP lease list as a router, a switch, a server or a PC prints it, from any vendor: each address seen with its MAC becomes a row.': 'または、ルーター、スイッチ、サーバー、PC が出力した ARP テーブルや DHCP リース一覧をそのまま貼り付けてください (メーカーは問いません)。MAC と一緒に検出された各アドレスが 1 行になります。',
