        'There is no switch or access point on the map to move them to.': '移動先にできるスイッチやアクセスポイントがマップ上にありません。',
        "Each one's cable moves to the next free port there. The device keeps its address: Move gives it one on another subnet.": '各デバイスのケーブルを移動先の次の空きポートに差し替えます。デバイスのアドレスはそのままです。別のサブネットのアドレスにするには「移動」を使います。',
        'Pick a switch to move them to.': '移動先のスイッチを選んでください。',
