        'Re-cable onto {switch}': '{switch} へ配線し直す',
        'Each cable moves to the next free port there, in the order shown. The cable keeps its label, length and colour, and each device keeps its address.': '各ケーブルを、表示された順に移動先の次の空きポートへ差し替えます。ケーブルのラベル、長さ、色はそのままで、各デバイスのアドレスも変わりません。',
        'File': 'ファイル',
        'Opens netplan.carino.systems pre-filled from this device (netplan / systemd-networkd / NetworkManager). Review the guessed fields before applying anything.': 'この機器の情報を入れた状態で netplan.carino.systems を開きます(netplan / systemd-networkd / NetworkManager)。適用する前に推測された項目を確認してください。',
        'Rows of subnets: {n}': 'サブネットの行: {n}',
        'A sheet of subnets maps only what a subnet has: its CIDR, name, VLAN, gateway and so on. Leave the other columns unmapped.': 'サブネットのシートで対応付けできるのはサブネットの項目(CIDR、名前、VLAN、ゲートウェイなど)だけです。ほかの列は対応付けないでください。',
        '{cidr} is not the range of this subnet ({now}). Renumber it in the Subnets tab, which moves its devices with it.': '{cidr} はこのサブネットの範囲({now})ではありません。Subnets タブでリナンバリングすると、機器も一緒に移ります。',
        '{id} and {cidr} are two different subnets.': '{id} と {cidr} は別々のサブネットです。',
        'A new subnet needs its CIDR, like 10.0.9.0/24.': '新しいサブネットには 10.0.9.0/24 のような CIDR が必要です。',
        "Found {name} by {key} only, but the row's {fields} belong to another device. Correct the sheet or the map so the two agree.": '{name} は {key} だけで見つかりましたが、行の {fields} は別の機器のものです。シートかマップを直して一致させてください。',
        'The pattern has no {type}, so every kind shares one run of numbers.': 'パターンに {type} がないため、すべての種類で番号が通しになります。',
        'Fold every wired NIC into one bond: one MAC, one address': '有線 NIC をすべて 1 つのボンドにまとめます: MAC 1 つ、アドレス 1 つ',
        'Show the hardware address under each interface — paste one and it is decoded': '各インターフェイスの下にハードウェアアドレスを表示します。貼り付けるとデコードされます',
        "NAT hides this device's private (inside) subnets from the WAN side — only the gateway itself is reachable from outside.": 'NAT はこの機器のプライベート(内側)サブネットを WAN 側から隠します。外部から到達できるのはゲートウェイ自身だけです。',
        'Say that this cloud stands for another network in your binder, so the estate report can draw the link between them.': 'このクラウドがバインダー内の別のネットワークを表すことを示します。全体レポートで両者のつながりが描かれます。',
        'Blank = All ports open': '空欄 = すべてのポートを開放',
