        'Filter the trace by a port. Off = IP reachability only — the port stays typed in, just ignored.': 'トレースをポートで絞り込みます。オフ = IP 到達性のみ。ポートは入力されたまま無視されます。',
        'Port to test when the Port filter is on': 'ポートフィルターがオンのときに試すポート',
